/**
 * Unit tests for FitnessFunction.repairAndDecode.
 */
public class FitnessFunction_repairAndDecode_TriageGen2Test {

    private CMAESOptimizer.FitnessFunction fitnessFunction;

    @Before
    public void setUp() {
        fitnessFunction = new CMAESOptimizer.FitnessFunction();
    }

    @Test
    public void testRepairAndDecodeWithValidArray() {
        // Arrange
        double[] input = {1.0, 2.0, 3.0};

        // Act
        // Since repairAndDecode calls decode(x), and decode is part of the same class,
        // we expect the output to be the result of decode(input).
        // In a unit test without a mock framework for the internal method, 
        // we assert based on the known identity that repairAndDecode(x) == decode(x).
        double[] result = fitnessFunction.repairAndDecode(input);
        double[] expected = fitnessFunction.decode(input);

        // Assert
        assertArrayEquals(expected, result, 1e-10);
    }

    @Test
    public void testRepairAndDecodeWithEmptyArray() {
        // Arrange
        double[] input = new double[0];

        // Act
        double[] result = fitnessFunction.repairAndDecode(input);
        double[] expected = fitnessFunction.decode(input);

        // Assert
        assertArrayEquals(expected, result, 1e-10);
    }

    @Test
    public void testRepairAndDecodeWithNull() {
        // Arrange
        double[] input = null;

        // Act & Assert
        // If decode(x) does not handle null, it will throw a NullPointerException.
        // Given the implementation is a direct delegation, we test for that behavior.
        try {
            double[] result = fitnessFunction.repairAndDecode(input);
            double[] expected = fitnessFunction.decode(input);
            assertArrayEquals(expected, result, 1e-10);
        } catch (NullPointerException e) {
            // Expected if decode doesn't handle null
        }
    }

    @Test
    public void testRepairAndDecodeWithLargeValues() {
        // Arrange
        double[] input = {Double.MAX_VALUE, Double.MIN_VALUE, Double.NaN, Double.POSITIVE_INFINITY};

        // Act
        double[] result = fitnessFunction.repairAndDecode(input);
        double[] expected = fitnessFunction.decode(input);

        // Assert
        assertArrayEquals(expected, result, 1e-10);
    }
}
